={{ (() => {
  const cfg = $json;
  const q = (value) => JSON.stringify(String(value));
  const workspaceRoot = cfg.workspaceRoot || '/workspace/agent-skills';
  const requirements = `${workspaceRoot}/ai-hotspot-collector/requirements.txt`;
  const targetOutput = cfg.outputDir || `${workspaceRoot}/content/ai-hotspot-digests`;
  const script = [
    'import importlib.util, pathlib, subprocess, sys',
    `requirements = ${q(requirements)}`,
    `target_output = ${q(targetOutput)}`,
    'pathlib.Path(target_output).mkdir(parents=True, exist_ok=True)',
    "if importlib.util.find_spec('requests') is None:",
    '    cmd = [sys.executable, "-m", "pip", "install", "-r", requirements]',
    '    subprocess.check_call(cmd)',
    'print("bootstrap-ready")'
  ].join("\\n");
  return 'python3 -c ' + JSON.stringify(script);
})() }}

={{ (() => {
  const cfg = $json;
  const q = (value) => JSON.stringify(String(value));
  const workspaceRoot = cfg.workspaceRoot || '/workspace/agent-skills';
  const parts = [
    'python3',
    q(`${workspaceRoot}/scripts/n8n_hotspot_bridge.py`),
    'prepare'
  ];

  if (cfg.existingPackageDir) {
    parts.push('--existing-package-dir', q(cfg.existingPackageDir));
  } else {
    parts.push('--sources', q(cfg.sources || 'hn,engadget,fast-company'));
    parts.push('--limit-per-source', String(cfg.limitPerSource || 3));
    parts.push('--rewrite-mode', q(cfg.rewriteMode || 'auto'));
    parts.push('--rewrite-provider', q(cfg.rewriteProvider || 'gemini'));
    parts.push('--rewrite-model', q(cfg.rewriteModel || 'gemini-3-pro-preview'));
    if (cfg.outputDir) parts.push('--output-dir', q(cfg.outputDir));
    if (cfg.date) parts.push('--date', q(cfg.date));
    if (cfg.keepDuplicates) parts.push('--keep-duplicates');
    if (cfg.failFast) parts.push('--fail-fast');
  }

  return parts.join(' ');
})() }}

parameters.jsCode:
const raw = ($json.stdout || '').trim();
if (!raw) {
  throw new Error('Prepare command returned empty stdout');
}
const data = JSON.parse(raw);
if (!data.ok) {
  throw new Error(`Prepare failed: ${data.error || data.stderr || raw}`);
}
return [{
  json: {
    ok: true,
    stage: 'prepared',
    packageDir: data.packageDir,
    digestPath: data.bundle?.digestPath || '',
    title: data.bundle?.title || '',
    summary: data.bundle?.summary || '',
    cover: data.bundle?.cover || '',
    files: data.bundle?.files || {},
    images: data.bundle?.images || [],
    sections: data.bundle?.sections || [],
    fetchExecuted: data.fetchExecuted,
    message: 'Hotspots collected and article bundle generated. Review the files under packageDir.'
  }
}];
